import 'dart:typed_data';

import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../data/models/match_mode.dart';
import '../../data/models/match_profile.dart';
import '../../data/models/pet_health_cert.dart';
import '../../data/models/pet_pedigree.dart';
import '../../data/repositories/matching_repository.dart';

class BreedingSetupState {
  const BreedingSetupState({
    required this.profile,
    required this.pedigree,
    required this.certs,
  });

  final MatchProfile? profile;
  final PetPedigree? pedigree;
  final List<PetHealthCert> certs;

  bool get hasVerifiedVaccination => certs.any(
        (c) =>
            c.certType == HealthCertType.vaccination &&
            c.verified &&
            (c.expiresAt == null || c.expiresAt!.isAfter(DateTime.now())),
      );

  bool get isReady => (profile?.isActive ?? false) && hasVerifiedVaccination;
}

final breedingSetupControllerProvider = AsyncNotifierProvider.family<
    BreedingSetupController, BreedingSetupState, String>(
  BreedingSetupController.new,
);

class BreedingSetupController
    extends FamilyAsyncNotifier<BreedingSetupState, String> {
  String get _petId => arg;

  @override
  Future<BreedingSetupState> build(String arg) => _load();

  Future<BreedingSetupState> _load() async {
    final repo = ref.read(matchingRepositoryProvider);
    final profile = await repo.fetchMatchProfile(_petId, MatchMode.breeding);
    final pedigree = await repo.fetchPedigree(_petId);
    final certs = await repo.fetchHealthCerts(_petId);
    return BreedingSetupState(
      profile: profile,
      pedigree: pedigree,
      certs: certs,
    );
  }

  Future<void> _refresh() async {
    state = AsyncData(await _load());
  }

  Future<void> saveProfile({
    required bool isActive,
    String? playStyle,
    String? energyLevel,
    String? preferredSize,
    String? availability,
  }) async {
    final repo = ref.read(matchingRepositoryProvider);
    await repo.saveMatchProfile(
      MatchProfile(
        petId: _petId,
        mode: MatchMode.breeding,
        isActive: isActive,
        playStyle: playStyle,
        energyLevel: energyLevel,
        preferredSize: preferredSize,
        availability: availability,
      ),
    );
    await _refresh();
  }

  Future<void> savePedigree({
    String? sireRef,
    String? damRef,
    String? registryName,
    String? registryId,
    String? titles,
  }) async {
    final repo = ref.read(matchingRepositoryProvider);
    await repo.savePedigree(
      PetPedigree(
        petId: _petId,
        sireRef: sireRef,
        damRef: damRef,
        registryName: registryName,
        registryId: registryId,
        titles: titles,
      ),
    );
    await _refresh();
  }

  Future<void> addCert({
    required HealthCertType certType,
    required Uint8List bytes,
    required String ext,
    required String contentType,
    DateTime? expiresAt,
  }) async {
    final repo = ref.read(matchingRepositoryProvider);
    await repo.addHealthCert(
      petId: _petId,
      certType: certType,
      bytes: bytes,
      ext: ext,
      contentType: contentType,
      expiresAt: expiresAt,
    );
    await _refresh();
  }

  Future<void> deleteCert(String id) async {
    final repo = ref.read(matchingRepositoryProvider);
    await repo.deleteHealthCert(id);
    await _refresh();
  }
}

import 'dart:async';

import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:petfolio/core/errors/app_exception.dart';
import 'package:petfolio/core/services/location_providers.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import '../datasources/matching_supabase_data_source.dart';
import '../models/chat_message.dart';
import 'dart:typed_data';

import '../models/match_mode.dart';
import '../models/match_profile.dart';
import '../models/pet_health_cert.dart';
import '../models/pet_pedigree.dart';
import '../models/matching_discovery_row.dart';
import '../models/pet_mutual_match.dart';
import '../models/pet_swipe.dart';

final matchingRepositoryProvider = Provider<MatchingRepository>(
  (ref) => MatchingRepository(
    ref,
    MatchingSupabaseDataSource(Supabase.instance.client),
  ),
);

class MatchingRepository {
  MatchingRepository(this._ref, this._dataSource);

  final Ref _ref;
  final MatchingSupabaseDataSource _dataSource;

  // Cache only confirmed-true results (location set is stable; "no location" can change).
  final Map<String, bool> _petLocationCache = {};

  Future<bool> actorPetHasLocation(String petId) async {
    if (_petLocationCache[petId] == true) return true;
    final hasLoc = await _dataSource.petHasLocation(petId);
    if (hasLoc) _petLocationCache[petId] = true;
    return hasLoc;
  }

  void invalidatePetLocationCache(String petId) {
    _petLocationCache.remove(petId);
  }

  /// Syncs the device's current GPS position to the pet's `location` column.
  ///
  /// Always acquires a fresh fix directly from [LocationService] — bypasses
  /// the cached [deviceLatLngProvider] to avoid stale-future and double-timeout
  /// issues (the provider's 4 s outer wrapper fires before the GPS's 12 s limit
  /// on devices that need more time, particularly emulators).
  ///
  /// Throws [ValidationException] when location permission is denied or the
  /// GPS read fails, and [DatabaseException] on a Supabase write failure.
  Future<void> syncActorLocationFromDevice(String activePetId) async {
    final coords =
        await _ref.read(locationServiceProvider).acquireCurrentLatLng();

    try {
      await _dataSource.setPetLocationPoint(
        petId: activePetId,
        latitude: coords.latitude,
        longitude: coords.longitude,
      );
      _petLocationCache[activePetId] = true;
    } on PostgrestException catch (e) {
      throw DatabaseException.fromPostgrest(e);
    }
  }

  Future<List<MatchingDiscoveryRow>> fetchCandidates({
    required String activePetId,
    int limit = 20,
    DateTime? cursorCreatedAt,
    String? cursorPetId,
    double radiusMeters = 80467,
    List<String>? speciesFilters,
    int? minAgeYears,
    int? maxAgeYears,
    MatchMode mode = MatchMode.playdate,
  }) async {
    final uid = _dataSource.currentUserId;
    if (uid == null) return [];

    final hasStoredLocation = await actorPetHasLocation(activePetId);
    if (!hasStoredLocation) {
      unawaited(
        syncActorLocationFromDevice(activePetId).catchError((_) {}),
      );
    }

    final species =
        (speciesFilters == null || speciesFilters.isEmpty) ? null : speciesFilters;

    return _dataSource.fetchDiscoveryCandidates(
      actorPetId: activePetId,
      radiusMeters: radiusMeters,
      limit: limit,
      cursorCreatedAt: cursorCreatedAt,
      cursorPetId: cursorPetId,
      speciesFilters: species,
      minAgeYears: minAgeYears,
      maxAgeYears: maxAgeYears,
      mode: mode.dbValue,
    );
  }

  Future<void> recordSwipe({
    required String swiperPetId,
    required String swipedPetId,
    required String swipedOwnerUserId,
    required String action,
    MatchMode mode = MatchMode.playdate,
  }) async {
    if (_dataSource.currentUserId == null) return;
    if (swipedPetId.startsWith('demo-')) return;

    final swipeAction = switch (action) {
      'pass' => SwipeTableAction.pass,
      'greet' => SwipeTableAction.greet,
      'superPaw' => SwipeTableAction.superPaw,
      _ => SwipeTableAction.like,
    };

    try {
      await _dataSource.insertSwipe(
        actorPetId: swiperPetId,
        targetPetId: swipedPetId,
        action: swipeAction,
        mode: mode.dbValue,
      );
    } catch (e) {
      debugPrint('[MatchingRepository] recordSwipe failed: $e');
      rethrow;
    }
  }

  Future<List<PetMutualMatch>> fetchMutualMatches(
    String petId, {
    MatchMode? mode,
  }) =>
      _dataSource.fetchMatchesForPet(petId, mode: mode?.dbValue);

  Future<List<PetSwipe>> fetchSwipesByActor(String actorPetId) =>
      _dataSource.fetchSwipesByActor(actorPetId);

  Future<Map<String, Map<String, dynamic>>> fetchPetsByIds(
          List<String> petIds) =>
      _dataSource.fetchPetsByIds(petIds);

  Future<void> setActivePetLocation({
    required String petId,
    required double latitude,
    required double longitude,
  }) async {
    await _dataSource.setPetLocationPoint(
      petId: petId,
      latitude: latitude,
      longitude: longitude,
    );
    _petLocationCache[petId] = true;
  }

  Future<MatchInboxSnapshot> fetchMatchInbox(String activePetId) =>
      _dataSource.fetchMatchInboxSnapshot(activePetId);

  Future<String> ensureChatThreadForMatch({
    required String matchId,
    required String actorPetId,
  }) =>
      _dataSource.ensureChatThreadForMatch(
        matchId: matchId,
        actorPetId: actorPetId,
      );

  Future<String> ensureDirectChatThread({
    required String actorPetId,
    required String otherPetId,
  }) =>
      _dataSource.ensureDirectChatThread(
        actorPetId: actorPetId,
        otherPetId: otherPetId,
      );

  Future<List<ChatMessage>> fetchMessages(
    String threadId, {
    int limit = 50,
    DateTime? beforeCreatedAt,
  }) =>
      _dataSource.fetchMessages(
        threadId,
        limit: limit,
        beforeCreatedAt: beforeCreatedAt,
      );

  Future<ChatMessage> sendMessage({
    required String threadId,
    required String content,
  }) =>
      _dataSource.sendMessage(threadId: threadId, content: content);

  Future<void> markMessagesAsRead(String threadId) =>
      _dataSource.markMessagesAsRead(threadId);

  Future<MatchProfile?> fetchMatchProfile(String petId, MatchMode mode) =>
      _dataSource.fetchMatchProfile(petId, mode.dbValue);

  Future<void> saveMatchProfile(MatchProfile profile) =>
      _dataSource.upsertMatchProfile(profile.toUpsert());

  Future<PetPedigree?> fetchPedigree(String petId) =>
      _dataSource.fetchPedigree(petId);

  Future<void> savePedigree(PetPedigree pedigree) =>
      _dataSource.upsertPedigree(pedigree.toUpsert());

  Future<List<PetHealthCert>> fetchHealthCerts(String petId) =>
      _dataSource.fetchHealthCerts(petId);

  Future<void> addHealthCert({
    required String petId,
    required HealthCertType certType,
    required Uint8List bytes,
    required String ext,
    required String contentType,
    DateTime? expiresAt,
  }) async {
    final path = await _dataSource.uploadHealthCertFile(
      petId: petId,
      bytes: bytes,
      certType: certType.dbValue,
      ext: ext,
      contentType: contentType,
    );
    await _dataSource.insertHealthCert({
      'pet_id': petId,
      'cert_type': certType.dbValue,
      'file_path': path,
      if (expiresAt != null)
        'expires_at': expiresAt.toIso8601String().split('T').first,
    });
  }

  Future<void> deleteHealthCert(String id) =>
      _dataSource.deleteHealthCert(id);

  Future<String> signedCertUrl(String filePath) =>
      _dataSource.signedCertUrl(filePath);
}

