      'file_path': path,
      if (expiresAt != null)
        'expires_at': expiresAt.toIso8601String().split('T').first,
    });
  }

  Future<void> deleteHealthCert(String id) =>
      _dataSource.deleteHealthCert(id);

  Future<String> signedCertUrl(String filePath) =>
      _dataSource.signedCertUrl(filePath);
}

