-- Phase 2: medication adherence logging + streak freeze

create table if not exists public.medication_logs (
  id uuid primary key default gen_random_uuid(),
  medical_record_id uuid not null references public.medical_vault(id) on delete cascade,
  pet_id uuid not null references public.pets(id) on delete cascade,
  given_at timestamptz not null default now(),
  given_by uuid references public.users(id),
  notes text,
  created_at timestamptz not null default now()
);
create index if not exists medication_logs_record_idx
  on public.medication_logs(medical_record_id, given_at desc);
create index if not exists medication_logs_pet_day_idx
  on public.medication_logs(pet_id, given_at desc);

alter table public.medication_logs enable row level security;

-- owner of the pet may manage dose logs
create policy medlog_select on public.medication_logs for select to authenticated
  using (exists (select 1 from public.pets p
                 where p.id = medication_logs.pet_id and p.owner_id = auth.uid()));
create policy medlog_insert on public.medication_logs for insert to authenticated
  with check (exists (select 1 from public.pets p
                      where p.id = medication_logs.pet_id and p.owner_id = auth.uid()));
create policy medlog_delete on public.medication_logs for delete to authenticated
  using (exists (select 1 from public.pets p
                 where p.id = medication_logs.pet_id and p.owner_id = auth.uid()));

-- streak freeze allowance (humane streaks)
alter table public.care_streaks
  add column if not exists freezes_available integer not null default 2;

