      case 1:
        return _ChoiceStep(
          title: 'How long has this been going on?',
          options: _durations,
          selected: _duration,
          onSelect: (v) => setState(() {
            _duration = v;
            _step = 2;
          }),
        );
      case 2:
        return _ChoiceStep(
          title: 'How severe does it seem?',
          options: const ['Mild', 'Moderate', 'Severe'],
          selected: _severity == null
              ? null
              : _severity!.name[0].toUpperCase() + _severity!.name.substring(1),
          onSelect: (v) => setState(() {
            _severity = switch (v) {
              'Severe' => HealthSeverity.severe,
              'Moderate' => HealthSeverity.moderate,
              _ => HealthSeverity.mild,
            };
            _step = 3;
          }),
        );
      default:
        final triage = _triage;
        return SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(18),
                decoration: BoxDecoration(
                  color: triage.resolve(context, pt).withValues(alpha: 0.16),
                  borderRadius: BorderRadius.circular(20),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(triage.level,
                        style: tt.titleLarge?.copyWith(
                            color: triage.resolve(context, pt),
                            fontWeight: FontWeight.w700)),
                    const SizedBox(height: 8),
                    Text(triage.guidance, style: tt.bodyMedium),
                  ],
                ),
              ),
              const SizedBox(height: 16),
              Text('Summary', style: tt.titleMedium),
              const SizedBox(height: 6),
              Text(
                '${_symptom ?? '—'} · ${_duration ?? 'urgent'}',
                style: tt.bodyMedium?.copyWith(color: pt.ink500),
              ),
              const SizedBox(height: 24),
              PrimaryPillButton(
                label: 'Save to health log',
                isFullWidth: true,
                isLoading: _saving,
                onPressed: _saving ? null : _save,
              ),
              const SizedBox(height: 8),
              TextButton(
                onPressed: () => setState(() {
                  _step = 0;
                  _symptom = null;
                  _duration = null;
                  _severity = null;
                }),
                child: const Text('Start over'),
              ),
            ],
          ),
        );
    }
  }
}

class _ChoiceStep extends StatelessWidget {
  const _ChoiceStep({
    required this.title,
    required this.options,
    required this.selected,
    required this.onSelect,
  });

  final String title;
  final List<String> options;
  final String? selected;
  final ValueChanged<String> onSelect;

  @override
  Widget build(BuildContext context) {
    final tt = Theme.of(context).textTheme;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(title, style: tt.titleLarge),
        const SizedBox(height: 12),
        Expanded(
          child: ListView(
            children: [
              for (final o in options)
                Padding(
                  padding: const EdgeInsets.only(bottom: 8),
                  child: ListTile(
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                      side: BorderSide(
                        color: Theme.of(context).dividerColor,
                      ),
                    ),
                    title: Text(o),
                    trailing: selected == o
                        ? const Icon(Icons.check_circle, size: 20)
                        : const Icon(Icons.chevron_right),
                    onTap: () => onSelect(o),
                  ),
                ),
            ],
          ),
        ),
      ],
    );
  }
}

class _DisclaimerBanner extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final pt = Theme.of(context).extension<PetfolioThemeExtension>()!;
    final tt = Theme.of(context).textTheme;
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: pt.warning.withValues(alpha: 0.14),
        borderRadius: BorderRadius.circular(14),
      ),
      child: Row(
        children: [
          Icon(Icons.info_outline, color: pt.warning, size: 20),
          const SizedBox(width: 10),
          Expanded(
            child: Text(
              'This is not a diagnosis. For emergencies, contact a vet immediately.',
              style: tt.bodySmall,
            ),
          ),
        ],
      ),
    );
  }
}

enum _TriageColor { ok, caution, urgent }

class _Triage {
  const _Triage({
    required this.level,
    required this.color,
    required this.guidance,
  });

  final String level;
  final _TriageColor color;
  final String guidance;

  Color resolve(PetfolioThemeExtension pt) => switch (color) {
        _TriageColor.ok => pt.success,
        _TriageColor.caution => pt.warning,
        _TriageColor.urgent => pt.pillarMatch,
      };
}

